    // 2. Adaptive Lookahead: Synergy with next item using non-linear scaling
    if next_item_size > 0 {
        let fit_diff = post_residual as i32 - next_item_size as i32;
        if fit_diff == 0 {
            score -= 680.0;
        } else if fit_diff > 0 {
            // Reward keeping space for the next item, decay as gap exceeds next_item_size
            score -= 420.0 * (1.0 - (fit_diff as f64 / bin_capacity as f64).powf(0.5));
        } else {
            // Penalize blocking the next item; scale by the ratio of waste to requirement
            score += 550.0 * (1.0 - (post_residual as f64 / next_item_size as f64).clamp(0.0, 1.0));
        }
    }

    // 3. New Bin Gatekeeping: Dynamic penalty based on progress and current utilization
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        // Increase base cost to be more conservative with new bins
        let mut new_bin_cost = 550.0 - (progress * 250.0);

        if fitting_bins_count > 0 {
            // Penalty for opening new bins when current ones have space
            new_bin_cost += (fitting_bins_count as f64).powf(1.9) * 165.0;
        }

        if mean_residual > (bin_capacity as f64 * 0.18) {
            new_bin_cost += 350.0;
        }
        score += new_bin_cost;
    }

    // 4. Utilization Pressure: Favor deep filling of existing bins
    let filled_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 480.0 * filled_ratio.powf(3.8);

    // 5. Fragmentation Mitigation: Penalize medium-sized "dead space" gaps (5-22%)
    let post_residual_ratio = post_residual as f64 / bin_capacity as f64;
    if post_residual_ratio > 0.05 && post_residual_ratio < 0.22 {
        score += 380.0 * (1.0 - (post_residual_ratio - 0.135).abs() * 7.0);
    }

    // 6. Global Entropy Constraint: Improved scaling
    if open_bins_count > 4 {
        let density = (mean_residual / bin_capacity as f64).clamp(0.02, 0.25);
        let expected_bins = (step_index as f64 * density).max(5.0);
        if (open_bins_count as f64) > expected_bins {
            score += 280.0 * ((open_bins_count as f64) / expected_bins).powf(2.5);
        }
    }

    score
}
